import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"New Features","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/README.md","filePath":"new-features/README.md"}'),o={name:"new-features/README.md"};function n(s,e,l,d,c,f){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h1><p>Open Algo is constantly evolving to meet the needs of modern traders by introducing innovative features that enhance functionality, security, and user experience. Each new addition focuses on improving performance, streamlining workflows, and enabling more efficient trading strategies. From cutting-edge tools to seamless integrations, these updates are tailored to empower both traders and developers.</p><p>The platform&#39;s current feature guides cover:</p><ul><li><a href="./agent/README">Agent</a> for the in-platform AI assistant: market data, charts, indicators, options analytics and approval-gated orders, on <code>/agent</code> and docked beside the chart on <code>/trading</code>.</li><li><a href="./portfolio-analytics">Portfolio Backtester and Analyzer</a> for authenticated, read-only portfolio simulation and current-holdings scenarios.</li><li><a href="./trading-terminal">Chart Trading Terminal</a> for multi-chart analysis, drawings, market depth, and order entry.</li><li><a href="./flow-visual-strategy-builder">Flow Visual Strategy Builder</a> for validated node graphs and schedule, webhook, price-alert, and order-update triggers.</li><li><a href="./python-strategy-hosting">Python Strategy Hosting</a> for process-isolated trusted scripts and scheduling.</li><li><a href="./historify">Historify</a> for local DuckDB history ingestion, scheduling, charts, and export.</li><li><a href="./fast-scalper">Scalping Terminal</a> for keyboard-driven entries with server-side stop and target monitoring.</li><li><a href="./api-analyzer">API Analyzer</a> for routing supported order flows into the sandbox instead of the live broker.</li><li><a href="./action-center">Action Center</a> for holding live orders in an approval queue in semi-auto mode.</li><li><a href="./pnl-tracker">PnL Tracker</a> for the intraday MTM and drawdown curve.</li><li><a href="./chartink-integration">Chartink Integration</a> for turning scanner alerts into orders.</li><li><a href="./traffic-latency-monitor">Traffic and Latency Monitor</a> for locally stored request metadata and timing records.</li><li><a href="./strategy-rms-engine">Strategy RMS Engine</a> for durable multi-leg and signal-driven strategy execution with run-level risk controls.</li></ul><p>Two feature areas are documented outside this section:</p><ul><li><a href="./../flow-editor/README">Flow Editor</a> is the full technical reference for Flow: the execution model, all 61 nodes, indicators, tutorials, and limitations.</li><li><a href="./../mcp/README">MCP</a> covers the built-in Model Context Protocol server, its 49 tools, and the optional OAuth-protected remote transport.</li></ul><p>Feature availability still depends on the active broker&#39;s supported exchanges, account entitlement, and market-data/order capabilities.</p>',7)])])}const p=t(o,[["render",n]]);export{h as __pageData,p as default};
